// План specs/admin-access.md, 4.1 (кейс AA-09). Admin «Kirill · Admin». Только чтение: внутри вкладок ничего не менять. @prod-safe
import { test, expect } from '@playwright/test';
import { setLanguage } from '../admin-plans/plans-helpers';
import { sectionTab, waitForMenu } from './access-helpers';

test.use({ storageState: '../auth/admin.json' });

test.describe('Admin Panel — admin как раньше (#12126fac)', () => {
  test('Admin sees "Kirill · Admin" in the header, Admin Panel and Support Console in the menu, and Users, Plans, Funnel tabs #12126fac @desktop @prod-safe', async ({ page }) => {
    await setLanguage(page, 'en');

    // Шаг 1: шапка и меню
    await page.goto('/dashboard');
    await waitForMenu(page);
    await expect(page.getByText('Kirill', { exact: true }).first()).toBeVisible();
    await expect(page.getByText('Admin', { exact: true }).first()).toBeVisible();
    await expect(page.getByRole('link', { name: 'Support Console' })).toBeVisible();
    const menuItem = page.getByRole('link', { name: 'Admin Panel' });
    await expect(menuItem).toBeVisible();

    // Шаг 2: из меню → /adminpanel, без редиректа
    await menuItem.click();
    await expect(page).toHaveURL(/\/adminpanel/);
    await expect(page.getByText('Access Denied')).toHaveCount(0);
    for (const t of ['Users', 'Plans', 'Funnel']) await expect(sectionTab(page, t).first()).toBeVisible();

    // Шаг 3: каждая вкладка открывается
    await sectionTab(page, 'Users').first().click();
    await expect(page).toHaveURL(/\/adminpanel/);
    await sectionTab(page, 'Plans').first().click();
    await expect(page.getByRole('heading', { name: 'Plans' })).toBeVisible();
    await expect(page).toHaveURL(/\/adminpanel/);
    await sectionTab(page, 'Funnel').first().click();
    await expect(page).toHaveURL(/\/adminpanel/);
  });
});
